/**
 * Loads the Rust core (ADR 0024) and makes the TypeScript core use it. G2 moves only the sky
 * sweep: `useRustSkySweep()` makes every world created afterwards sweep its light in Rust, bit for
 * bit as the TypeScript sweep does.
 *
 * It loads the parity build (pkg-parity/, the core's Math as V8's), generated by
 * `node cli/build-wasm.ts` (part of `npm run check`) and not committed.
 */

import { setSkySweepFactory } from "../core/world.ts";
import init, { type InitOutput, initSync } from "./pkg-parity/core.js";
import { WasmSkySweep } from "./sky-sweep.ts";

let instance: InitOutput | null = null;

/** The loaded module's exports (its memory, chiefly), or an error if it is not loaded. */
export function wasm(): InitOutput {
  if (!instance) throw new Error("The Rust core is not loaded: call loadCore or loadCoreSync");
  return instance;
}

/** Loads the module from its bytes (Node: `readFileSync(coreWasmUrl)`). */
export function loadCoreSync(bytes: Uint8Array | ArrayBuffer): void {
  instance ??= initSync({ module: bytes });
}

/** Loads the module by fetching it (the page, after first paint). */
export async function loadCore(url: URL | string = coreWasmUrl): Promise<void> {
  instance ??= await init({ module_or_path: url });
}

/** Where the module sits next to this file. */
export const coreWasmUrl = new URL("./pkg-parity/core_bg.wasm", import.meta.url);

/** Makes worlds created from now on sweep their light in Rust (or in TypeScript again). */
export function useRustSkySweep(on = true): void {
  wasm();
  setSkySweepFactory(
    on ? (width, height, c2, periodic) => new WasmSkySweep(width, height, c2, periodic) : null,
  );
}
